'use strict';

// MODULES //

var tape = require( 'tape' );
var concat = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof concat, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function concatenates two strings', function test( t ) {
	var expected;
	var actual;

	actual = concat( 'Hello ', 'World!' );
	expected = 'Hello World!';
	t.strictEqual( actual, expected, 'concatenates two strings' );

	actual = concat( 'Beep ', 'Boop' );
	expected = 'Beep Boop';
	t.strictEqual( actual, expected, 'concatenates two strings' );

	actual = concat( 'foo', 'bar' );
	expected = 'foobar';
	t.strictEqual( actual, expected, 'concatenates two strings' );

	actual = concat( '', 'World!' );
	expected = 'World!';
	t.strictEqual( actual, expected, 'concatenates empty string with non-empty string' );

	actual = concat( 'Hello ', '' );
	expected = 'Hello ';
	t.strictEqual( actual, expected, 'concatenates non-empty string with empty string' );

	actual = concat( '', '' );
	expected = '';
	t.strictEqual( actual, expected, 'concatenates two empty strings' );

	t.end();
});
